  IF NOT EXISTS (SELECT 1 FROM __mj."Graph" WHERE "ID" = p_ID_ab3168ca22ca) THEN
    IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = '__mj' AND p.proname = 'spCreateGraph' AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype) THEN
