-- Save MJ: Actions (core SP call only)
DO $mj$
DECLARE
  p_Description_a8c6ea3ea06d TEXT;
  p_ID_a8c6ea3ea06d UUID;
BEGIN
  p_Description_a8c6ea3ea06d := 'Returns a bounded neighborhood of a semantic graph (default "MJ Canon") around concepts matching a natural-language Question and/or explicit seed nodes: the nodes and edges as JSON and as compact prompt text. Every node is one the caller may see. Use it to find the canonical definition of a business term and the views, queries and entities that define, measure or describe it. Returns AMBIGUOUS_CONCEPT with the candidate concepts when the question fits several equally well, NO_MATCH when nothing matches, and fails with GRAPH_NOT_FOUND when the graph is unknown or not active.';
  p_ID_a8c6ea3ea06d := 'A39B5FF6-A7DD-4851-9172-32713A601273';
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = '__mj' AND p.proname = 'spUpdateAction' AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype) THEN
    PERFORM __mj."spUpdateAction"(p_data := jsonb_build_object(
    'Description', p_Description_a8c6ea3ea06d,
    'ID', p_ID_a8c6ea3ea06d
  ));
  ELSE
    PERFORM __mj."spUpdateAction"(p_Description := p_Description_a8c6ea3ea06d, p_ID := p_ID_a8c6ea3ea06d);
  END IF;
END $mj$;

