-- Save MJ: Actions (core SP call only)
DO $mj$
DECLARE
  p_Description_c48fbe138566 TEXT;
  p_ID_c48fbe138566 UUID;
BEGIN
  p_Description_c48fbe138566 := 'Scores a set of records with a trained ML Model. The scope selects records (explicit ids / a saved view / a list / an entity+filter / a single record). With a BindingID the binding''s pipeline''s Published model scores the scope and the scores are written as the binding''s Feature Values (and copied into its column, when it names one); without one the model predicts and the predictions are returned, writing nothing, for a scope of at most 250 records (a larger one is refused with READ_CAP_EXCEEDED before scoring). Outputs the scoring run: ScoringRunID, Status, Total, Written, Failed, and Predictions when nothing was written. A refused or failed run fails the action with the refusal''s code and still names its scoring run.';
  p_ID_c48fbe138566 := '745B8BDC-B748-42F0-82E2-25C5E0615777';
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = '__mj' AND p.proname = 'spUpdateAction' AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype) THEN
    PERFORM __mj."spUpdateAction"(p_data := jsonb_build_object(
    'Description', p_Description_c48fbe138566,
    'ID', p_ID_c48fbe138566
  ));
  ELSE
    PERFORM __mj."spUpdateAction"(p_Description := p_Description_c48fbe138566, p_ID := p_ID_c48fbe138566);
  END IF;
END $mj$;

-- Save MJ: Actions (core SP call only)
DO $mj$
DECLARE
  p_Description_dd75d5b23d03 TEXT;
  p_ID_dd75d5b23d03 UUID;
BEGIN
  p_Description_dd75d5b23d03 := 'Applies one lifecycle Transition to an ML Model through the Predictive Studio lifecycle gate: evaluate (Draft to Validated or KeepBaseline from the training run''s stored gate decision), publish (Validated or KeepBaseline to Published, re-verified from the stored rows), archive (to Archived, Reason required) or rollback (Archived to Published for a model published before, Reason required). A model whose training run flagged possible target leakage is withheld until a person records a sign-off in the model detail. Lifecycle-only: never edits the model''s metrics or artifact, only its Status.';
  p_ID_dd75d5b23d03 := 'FD787F18-C8C4-4C50-8735-A029F41BC478';
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = '__mj' AND p.proname = 'spUpdateAction' AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype) THEN
    PERFORM __mj."spUpdateAction"(p_data := jsonb_build_object(
    'Description', p_Description_dd75d5b23d03,
    'ID', p_ID_dd75d5b23d03
  ));
  ELSE
    PERFORM __mj."spUpdateAction"(p_Description := p_Description_dd75d5b23d03, p_ID := p_ID_dd75d5b23d03);
  END IF;
END $mj$;

-- Save MJ: Action Params (core SP call only)
DO $mj$
DECLARE
  p_Description_51ed2201fb4d TEXT;
  p_ID_51ed2201fb4d UUID;
