    'Description', p_Description_dbeb40893fec,
    'Instructions', p_Instructions_dbeb40893fec,
    'ID', p_ID_dbeb40893fec
  ));
  ELSE
    PERFORM __mj."spUpdateAISkill"(p_Description := p_Description_dbeb40893fec, p_Instructions := p_Instructions_dbeb40893fec, p_ID := p_ID_dbeb40893fec);
  END IF;
END $mj$;

