DO $mj$
DECLARE
  v_full TEXT;
BEGIN
  SELECT to_jsonb(v)::text INTO v_full FROM __mj."vwQueryParameters" v WHERE v."ID" = 'B302A357-F999-4D41-9B68-DAE2A0F48DF9';
  IF FOUND THEN
    PERFORM __mj."spCreateRecordChange_Internal"(
      p_EntityName := 'MJ: Query Parameters',
