      p_Type := 'Create',
      p_ChangesJSON := '',
      p_ChangesDescription := 'Record Created',
      p_FullRecordJSON := v_full,
      p_Status := 'Complete',
      p_Comments := NULL,
      p_EntityID := '3D08228D-8D64-46D3-AED9-AABD54BBBDBE',
      p_SuppressReturn := TRUE
    );
  END IF;
END $mj$;


