    /** The path as compact Markdown, one line per hop. */
    PromptText: string;
    /** Which endpoint was ambiguous or not found, when that is the status. */
    Endpoint?: ''From'' | ''To'';
    Candidates: GraphFindPathCandidate[];
    Message?: string;
}
';
  p_OutputTypeIsArray_7bac768f1f09 := FALSE;
